/* Growing film-photo constellation inspired by the supplied motion reference. */
(()=>{'use strict';const entry=document.getElementById('entry');if(!entry)return;
const canvas=document.createElement('canvas');canvas.className='journey-canvas';canvas.setAttribute('aria-hidden','true');entry.prepend(canvas);const ctx=canvas.getContext('2d');let photos=[],last=0,time=0,previous=0,wasClosed=true;const nodes=[];
function node(x,y,parent,depth,birth,size){const i=nodes.length;nodes.push({x,y,parent,depth,birth,size,image:i%26,phase:i*1.73});return i}
// Two continuous trunks, each splitting through three generations of real branches.
for(const side of [-1,1]){let trunk=node(side*.32,.51,-1,0,0,0);for(let level=0;level<7;level++){const x=side*(.31+Math.sin(level*.85)*.035),y=.39-level*.135;trunk=node(x,y,trunk,0,level*.58,level%2?26:0);for(const direction of [-1,1]){const b=node(x+direction*.065,y-.03,trunk,1,level*.58+.4,0);for(const fork of [-1,1]){const c=node(nodes[b].x+direction*.045,y-.065+fork*.025,b,2,level*.58+.85,28);for(const twig of [-1,1])node(nodes[c].x+direction*.03,nodes[c].y+twig*.026,c,3,level*.58+1.3,12)}}}}
fetch('assets/journey/manifest.json').then(r=>r.json()).then(async films=>{photos=await Promise.all(films.map(f=>new Promise(resolve=>{const im=new Image();im.onload=()=>{const thumb=document.createElement('canvas');thumb.width=112;thumb.height=140;const c=thumb.getContext('2d'),s=Math.max(112/im.width,140/im.height),sw=112/s,sh=140/s;c.filter='sepia(.34) saturate(.48)';c.drawImage(im,(im.width-sw)/2,(im.height-sh)*.2,sw,sh,0,0,112,140);resolve(thumb)};im.onerror=()=>resolve(null);im.src=f.src})));entry.classList.add('journey-ready')}).catch(()=>{});
const ease=x=>1-Math.pow(1-Math.max(0,Math.min(1,x)),3);
function frame(now){requestAnimationFrame(frame);if(document.hidden||entry.hidden||entry.classList.contains('out')){previous=now;wasClosed=true;return}if(now-last<42)return;last=now;if(wasClosed){time=0;wasClosed=false}const reduced=document.body.classList.contains('reduced')||matchMedia('(prefers-reduced-motion: reduce)').matches;if(!reduced)time+=Math.min((now-(previous||now))/1000,.1);previous=now;if(!photos.length)return;
const w=entry.clientWidth,h=entry.clientHeight,dpr=Math.min(devicePixelRatio,1.5);if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr)}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);const t=reduced?12:time,zoom=1.1-.1*ease(t/16),sizeScale=Math.max(.58,Math.min(w/1100,1.25));
const positions=nodes.map(n=>({x:w*.5+(n.x*w+Math.sin(t*.25+n.y*4)*5)*zoom,y:h*.5+(n.y*h+Math.cos(t*.18+n.x*5)*4)*zoom,alpha:ease((t-n.birth)/.75)}));
nodes.forEach((n,i)=>{const p=positions[i];if(!p.alpha||n.parent<0)return;const parent=positions[n.parent],bend=(p.x-parent.x)*.2;ctx.strokeStyle=`rgba(133,73,42,${(n.depth===0?.72:.52)*p.alpha})`;ctx.lineWidth=n.depth===0?2.4:n.depth===1?1.65:.85;ctx.beginPath();ctx.moveTo(parent.x,parent.y);const ex=parent.x+(p.x-parent.x)*p.alpha,ey=parent.y+(p.y-parent.y)*p.alpha;ctx.bezierCurveTo(parent.x+bend,parent.y-12,ex-bend,ey+9,ex,ey);ctx.stroke();if(!reduced){const q=(t*.23+n.phase)%1;ctx.shadowColor='#dcaa62';ctx.shadowBlur=8;ctx.fillStyle=`rgba(190,113,45,${.85*p.alpha})`;ctx.beginPath();ctx.arc(parent.x+(p.x-parent.x)*q,parent.y+(p.y-parent.y)*q,n.depth?1.7:2.6,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0}});
nodes.forEach((n,i)=>{const p=positions[i],im=photos[n.image%photos.length];if(!im||p.alpha<.9||!n.size)return;const s=n.size*sizeScale*(.72+.28*p.alpha),hh=s*1.25;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(Math.sin(n.phase)*.045);ctx.globalAlpha=p.alpha*(n.size>20?.88:.65);ctx.shadowColor='rgba(80,58,37,.2)';ctx.shadowBlur=5;ctx.fillStyle='#faf4e9';ctx.fillRect(-s/2-2,-hh/2-2,s+4,hh+4);ctx.shadowBlur=0;ctx.drawImage(im,-s/2,-hh/2,s,hh);ctx.restore()});
}requestAnimationFrame(frame);
})();
